window.DOSIK=window.DOSIK||{};DOSIK["fr_biz"]={"1":[{"t":"table","title":"손실 거래","head":["사건","내용"],"rows":[["도난","진열장에 진열된 제품 200,000원을 도난당하였다"],["화재","화재로 인해 제품 100,000원이 소실되었다"],["폭우","폭우로 인해 상품 20만원이 소실되었다"],["파산","거래처의 파산으로 매출채권 100,000원이 회수불능되었다"]]},{"t":"table","title":"일반 거래","head":["거래","내용"],"rows":[["구매 계약","원료 공급회사와 구매 계약을 체결하고 계약금 100,000원을 지급하였다"],["차입","주거래은행에서 10만원을 차입하였다"],["급여","종업원에게 급여 30만원을 지급하였다"],["이자 발생","차입금 이자 5만원이 발생하였으나 아직 지급하지 않았다"]]},{"t":"table","title":"계정과목","head":["경우","기록"],"rows":[["건물 양도 대금 미수","건물을 양도하고 대금 중 일부를 받지 못한 경우 미수금으로 기록한다"],["계약금 지급","상품대금의 일부를 계약금으로 지급한 경우 선급금으로 기록한다"],["이자수익 미수","이자수익이 발생하였으나 아직 현금으로 지급받지 못한 경우 미수수익으로 기록한다"],["기간 미경과 보험료","결산일 현재 기간이 경과되지 않은 보험료는 선급보험료로 기록한다"]]}],"2":[{"t":"cause","title":"기말재고 오류","causes":["20×1년 매출원가가 10,000원 과소계상된다","20×1년 당기순이익이 10,000원 과대계상된다"],"result":"20×2년 기초재고 10,000원 과대","effects":["20×2년 당기순이익이 10,000원 과소계상된다"]},{"t":"table","title":"유형자산","head":["항목","내용"],"rows":[["감가상각누계액","20×2년 말 재무상태표에 계상될 감가상각누계액은 6,300원이다"],["처분손익","유형자산의 처분으로 인한 손익은 처분시점의 장부가액과 순매각금액의 차액으로 결정된다"]]}],"3":[{"t":"tree","title":"CVP분석의 가정","root":"CVP분석","branches":[["판매가격","단위당 판매가격은 판매량에 관계없이 일정하다 · 판매가격은 일정범위 내에서는 변동하지 않는다"],["원가 구분","모든 원가는 고정비와 변동비로 나누어진다"],["원가요소","원가요소, 능률, 생산성은 일정범위 내에서 변동하지 않는다"]]},{"t":"def","term":"시스템 비용","text":"시스템 유지와 업데이트 비용이 크다"}],"4":[{"t":"flow","title":"정보처리과정","steps":["노출은 자극이 감각기관에 들어오는 것이다","주의는 정보처리자원을 특정 자극에 집중하는 인지작용이다","이해(해석)는 유입된 정보를 조직하고 그 의미를 해석하는 것이다","기억은 처리된 정보를 저장하는 것이다"]}],"5":[{"t":"table","title":"브랜드전략","head":["개념","내용"],"rows":[["브랜드","자사제품을 식별시키고 경쟁사의 제품으로부터 차별화시킬 목적으로 사용하는 이름, 어구, 기호, 상징 또는 이들의 결합을 말한다"],["브랜드확장전략","한 제품시장에서 성공을 거둔 기존의 브랜드명을 사용하여 다른 제품범주의 신제품에도 사용하는 전략을 말한다"],["공동브랜드(family brand)","여러 개별 제품에 동일한 브랜드를 적용하는 것을 말하며, 제품계열단위로 사용되기도 한다"],["브랜드 자산","브랜드 자산의 원천은 브랜드 인지도와 브랜드 이미지이다"]]},{"t":"table","title":"제품수명주기","head":["단계","마케팅"],"rows":[["도입기","중간상판촉을 통해 자사제품의 진열을 유도하는 것이 필요하다"],["성장기","마케팅 목표는 브랜드강화를 통해 시장점유율을 빠르게 확대시키는 것이다 · 일반소비자층의 시용구매를 확대하기 위해 판매촉진비를 계속 증가시킨다"],["성숙기","시장 확대를 위해 적극적 브랜드재활성화 전략이 필요하다"]]},{"t":"tree","title":"시장세분화 요건","root":"세분시장","branches":[["이질성","각 세분시장은 서로 이질성이 있어야 한다"],["측정가능성","각 세분시장은 측정가능성이 있어야 한다"],["접근가능성","각 세분시장은 접근가능성이 있어야 한다"],["규모","각 세분시장은 충분한 규모가 되어야 한다"]]}],"6":[{"t":"table","title":"가격 개념","head":["개념","내용"],"rows":[["유인가격(loss-leader pricing)","소비자들에게 잘 알려진 제품에 대하여 원가와 무관하게 낮은 가격을 제시하는 가격설정방식이다 · 일부 제품에 대해 원가와 무관하게 낮은 가격을 제시하는 것이다"],["유보가격(reservation price)","소비자가 어떤 제품에 대해 지불할 의사가 있는 최고 가격이다"],["준거가격(reference price)","소비자들이 제품가격이 비싼지 싼지를 평가할 때 비교 기준으로 사용하는 가격이다 · 구매자가 가격이 비싼지 싼지를 판단하는 기준으로 삼는 가격이다"],["최저수용금액","구매자가 의심하지 않고 구매할 수 있는 최저금액이다"]]},{"t":"table","title":"가격전략","head":["전략","내용"],"rows":[["종속제품가격(captive-product pricing)","특정제품과 반드시 함께 사용되는 제품에 대해 부과하는 가격결정방식이다"],["묶음가격(bundling pricing)","복수의 자사 제품을 묶음으로 저렴하게 제시할 때 사용하는 가격결정방식이다"],["단수가격조정","끝자리를 미세한 단위(∼ 9원)로 정하는 방식이다"]]}],"7":[{"t":"vs","title":"푸시 전략과 풀 전략","cols":[{"name":"푸시(push) 전략","items":["제조업체가 유통경로를 통하여 소비자에게 제품을 밀어 내는 방식이다"]},{"name":"풀(pull) 전략","items":["제조업체 A가 소비자들을 대상으로 광고를 하고, 소비자들이 점포에서 A기업 제품을 주문하도록 유도한다","효과적으로 작용하게 되면 소비자들은 자발적으로 유통업체에 가서 제품을 구매하게 된다"]}]},{"t":"def","term":"판매촉진","text":"푸시(push) 전략과 풀(pull) 전략 모두에서 사용된다"},{"t":"tree","title":"VMS","root":"VMS","branches":[["계약형 VMS","경로 구성원들 간의 명시적인 계약을 통해 경로관계가 형성된다"],["기업형 VMS","계약형 VMS보다 경로 구성원들에게 더 강한 통제력을 행사할 수 있다"],["관리형 VMS","명시적인 계약에 의하지 않고 운영되는 특성이 있다"],["힘의 집중","VMS에서는 특정 경로 구성원에게 힘이 집중되는 특성이 있다"]]},{"t":"vs","title":"광고와 판매촉진","cols":[{"name":"광고","items":["중장기적인 효과를 추구","브랜드 관련 기억증가의 효과를 추구","간접적이고 보통 수준의 당기 이익에 공헌","브랜드를 인식하지 못한 소비자를 목표 고객으로 함"]},{"name":"판매촉진","items":["단기적인 효과를 추구","판매의 즉각적인 증가 효과를 추구","직접적이고 높은 수준의 당기 이익에 공헌","타사 브랜드 애용자를 목표 고객으로 함"]}]}],"8":[{"t":"table","title":"투자안 평가방법","head":["방법","내용"],"rows":[["회수기간법","투자에 소요된 모든 비용을 회수하는데 걸리는 기간만을 고려하여 투자안을 평가하는 방법이다"],["수익성지수법","투자로 인하여 발생하는 현금유입의 현가를 현금유출의 현가로 나누어 투자안을 평가하는 방법이다"],["순현재가치법","순현가(NPV)란 투자의 결과 발생하는 현금유입의 현가에서 현금유출의 현가를 차감한 것을 말한다 · 화폐의 시간적 가치를 반영한 평가방법이다 · 가치가산의 원리가 성립한다"],["내부수익률법","내부수익률(IRR)은 투자안의 현금유입의 현가와 현금유출의 현가가 같아지게 하는 할인율을 말한다"]]},{"t":"def","term":"내부수익률(IRR)","text":"투자안의 연평균수익률을 의미한다","ex":["순현가(NPV)가 0이 되는 할인율이다","내부수익률이 자본비용보다 크면 투자한다","내부수익률은 투자안의 현금유입의 현재가치와 현금유출의 현재가치를 일치시키는 할인율이다"]},{"t":"def","term":"현금유출","text":"이자비용과 배당금은 현금유출에 포함하지 않는다","ex":["화폐의 시간적 가치를 고려한다"]}],"9":[{"t":"tree","title":"포트폴리오의 위험","root":"총위험","branches":[["체계적위험","체계적위험은 시장위험이라고도 한다 · 체계적 위험을 측정하는 방법으로 베타계수를 사용할 수 있다"],["비체계적위험","총위험은 체계적위험과 비체계적위험으로 구성된다"]]},{"t":"table","title":"베타","head":["내용"],"rows":[["시장포트폴리오 베타 값은 1이다"],["개별 주식의 체계적 위험을 계산할 때 사용한다"],["베타 값이 1보다 크면 공격적 자산, 1보다 작으면 방어적 자산이라 한다"],["개별 주식과 시장포트폴리오의 공분산을 시장포트폴리오의 분산으로 나눈 값이다"]]},{"t":"tree","title":"분산투자","root":"분산투자","branches":[["구성종목 수","구성종목 수가 많을수록 위험은 작아진다"],["상관계수","위험은 주식 간 상관계수에 따라 달라진다 · 구성자산들간의 상관계수가 낮을수록 분산투자효과가 높은 편이다"],["격언","‘계란을 한 바구니에 담지 말라’는 포트폴리오 투자를 대표하는 격언이다"],["ETF","KODEX200 ETF에 투자하는 것은 분산투자의 일종이다"]]}],"11":[{"t":"table","title":"채권가치","head":["내용"],"rows":[["채권수익률이 하락하면 채권가격은 상승한다"],["채권의 이자율변동에 대한 위험은 만기가 길수록 더 크다"],["채권수익률이 액면이자율과 동일하면 채권의 가치는 액면가와 동일하다"],["채권의 가치는 만기가 가까워질수록 액면가에 접근한다"]]},{"t":"vs","title":"배당이론","cols":[{"name":"배당유관설","items":["고든(M. Gordon)의 ‘손 안에 있는 새’는 배당유관설과 관련이 있다"]},{"name":"배당무관설","items":["밀러(M. Miller)와 모딜리아니(F. Modigliani)는 배당무관설을 주장했다"]}]},{"t":"vs","title":"배당 형태","cols":[{"name":"액면분할","items":["이론상 기업의 가치에 아무런 영향을 주지 않는다"]},{"name":"현금배당","items":["배당락이 있다"]},{"name":"자사주매입","items":["배당락이 없는 배당의 특수형태라고 할 수 있다"]}]}],"12":[{"t":"table","title":"개인특성","head":["개념","내용"],"rows":[["내재론자(internal locus of control)","자신에게 일어나는 일을 통제할 수 있다고 믿으면 내재론자라고 한다"],["자기효능감(self-efficacy)","특정 과업을 얼마나 잘 수행할 수 있는가에 대한 믿음이다"],["자기관찰(self-monitoring)","환경의 신호를 읽고 해석하여 자신의 행위를 환경요구에 맞춰 조절해가는 성향이다"],["마키아벨리즘(machiavellism)","자신의 목적을 위해 다른 사람을 이용하고 통제하려는 성향이다"]]}],"14":[{"t":"tree","title":"네트워크 조직","root":"네트워크 조직","branches":[["신뢰관계","수직적, 수평적, 공간적 신뢰관계로 연결된 조직형태이다"],["제약","기존 네트워크로부터 행동을 제약받는 압박이 발생할 수 있다"],["투자","공장, 유통시설 등에 막대한 투자가 없어도 사업을 할 수 있다"],["핵심기능","핵심기능만 보유하고 나머지 기능은 아웃소싱을 할 수 있다"]]},{"t":"table","title":"브레인스토밍","head":["규칙","내용"],"rows":[["비판 금지","타인의 아이디어에 대해 비판해서는 안 된다"],["자유로운 제시","자유롭게 아이디어를 제시할 수 있어야 한다"],["양","가능한 많은 아이디어를 제시하도록 한다"],["수정","타인의 아이디어를 수정하여 제시하는 것이 허용된다"]]}],"15":[{"t":"tree","title":"인사평가의 효과","root":"인사평가","branches":[["의사소통","관리자와 부하직원들 간의 의사소통이 개선된다"],["조직의 목표","개인들이 조직의 목표를 보다 더 잘 알게 한다"],["피드백","체계적 피드백 제공으로 직무수행이 개선된다"],["기대","조직이 개인들에게 기대하는 바가 무엇인지를 알게 한다"]]}],"17":[{"t":"tree","title":"식스 시그마","root":"식스 시그마","branches":[["변동","변동의 감소는 중요한 목표이다"],["측정","타당한 측정을 통해 데이터 중심의 방법론을 적용한다"],["핵심 투입 요소","소수의 핵심적인 투입 요소가 결과에 커다란 영향을 미친다"],["최고경영층","최고경영층의 참여가 필수적이다"]]},{"t":"table","title":"품질 기법","head":["기법","내용"],"rows":[["동시공학","concurrent engineering: 제품 및 서비스 · 개발과 관련된 다양한 부서원들이 공동 참여하는 방식이다"],["품질기능전개","quality function deployment: · 고객의 요구사항을 설계특성으로 변환하는 방법이다"],["가치분석·가치공학","value analysis / value engineering: · 제품의 가치를 증대시키기 위한 체계적 방법이다"],["강건설계","robust design: 제품이 작동환경의 영향을 덜 받고 기능하도록 하는 방법이다"]]},{"t":"tree","title":"품질비용","root":"품질비용","branches":[["품질비용","100 % 완전하지 못한 제품생산으로 인한 비용이다"],["평가비용","검사, 측정, 시험 등과 관련한 비용이다"],["통제비용","생산흐름으로부터 불량을 제거하기 위한 활동과 관련된 비용이다"],["실패비용","완성된 제품의 품질이 일정한 수준에 미달함으로써 발생하는 비용이다"]]}],"18":[{"t":"def","term":"재고회전율","text":"기본적인 성과지표로 미납주문의 양과 고객 불평의 횟수를 사용할 수 있다","ex":["제조와 판매에 오랜 시간이 걸리는 제품은 재고회전율이 낮다","이윤 폭이 적은 슈퍼마켓은 상당히 높은 회전율을 가져야 한다","재고 공급 일수는 특정 시점에 시스템에서 보유하고 있는 재고로 · 얼마나 수요를 감당할 수 있는지를 나타내는 척도로 사용한다"]},{"t":"table","title":"변화의 영향","head":["변화","결과"],"rows":[["연간 수요가 감소하면","경제적 주문량은 감소한다"],["재고유지비용이 감소하면","재고회전율은 감소한다"],["주문비용이 감소하면","재고회전율은 증가한다 · 공급주수(weeks of supply)는 감소한다"]]},{"t":"vs","title":"Q-모형과 P-모형","cols":[{"name":"Q-모형","items":["주문량이 일정하다","재고량이 재주문점에 이를 때 주문한다","반입ㆍ반출 시 재고량을 파악한다","고가이고 중요한 품목에 활용된다"]},{"name":"P-모형","items":["주문량이 변동한다","정기적으로 주문한다","점검시기에 재고량을 파악한다","저가 품목에 활용된다"]}]}],"19":[{"t":"tree","title":"오픈소스 소프트웨어","root":"오픈소스 소프트웨어","branches":[["개발자 커뮤니티","소스 코드를 작성하고 수정하는 개발자 커뮤니티를 가지고 있다"],["소프트웨어 산업","소프트웨어 산업은 사유(독점) 소프트웨어(proprietary software)에서 오픈소스 소프트웨어로 나아가는 경향이 있다"],["유연성","사용자의 요구를 만족시키기 위해 코드가 수정될 수 있는 유연성을 가진다"],["오픈소스 CRM","오픈소스 CRM 시스템은 소스 코드가 개발자와 사용자에게 공개된 CRM 소프트웨어를 말한다"]]},{"t":"def","term":"데이터 마이닝","text":"패턴과 관계를 발견하기 위한 분석이다","ex":["데이터 그 자체만으로 제공되지 않는 정보를 추출하기 위해 자료를 분석한다","구조적 자료뿐만 아니라 비구조적 자료에 대해서도 분석을 할 수 있다","마이닝 기법으로 사용되는 분석 방법으로 군집분석, 연관성분석, 통계분석 등이 있다"]},{"t":"def","term":"Paas","text":"사용자들은 기존의 애플리케이션을 실행할 수 있고, 새로운 애플리케이션을 개발하여 테스트할 수도 있다"},{"t":"table","title":"지식 전환","head":["전환","내용"],"rows":[["지식 공유와 창출","암묵지(implicit knowledge)와 형식지(explicit knowledge)의 전환과정에서 지식이 공유되고 창출된다"],["외재화(externalization)","암묵지에서 형식지로 전환과정을 외재화라 한다"],["결합화(combination)","형식지에서 형식지로 전환과정을 결합화라 한다"]]}],"20":[{"t":"def","term":"BCG 매트릭스","text":"미국의 보스턴 컨설팅 그룹이 개발한 사업전략 분석 기법이다","ex":["사업의 매력도를 평가하기 위해 시장성장률을 사용한다","사업의 경쟁력을 평가하기 위해 상대적 시장점유율을 사용한다","사업부의 분면 위치는 시간이나 시장 환경에 따라 재평가되어야 한다"]},{"t":"tree","title":"사업단위 유형","root":"BCG 매트릭스","branches":[["Star","고성장 시장에 있으면서 상대적 시장점유율이 높은 사업단위이다 · 지속적인 투자가 요구되는 영역이다 · 제품수명주기 상의 성장기에 위치하며 많은 경쟁자들이 시장에 진출할 것으로 예상된다 · 높은 시장점유율을 유지하기 위해서는 상당한 자금투입이 요구된다"],["Dog","시장성장률과 상대적 시장점유율이 모두 낮은 영역이다"],["자금흐름","현시점에서 기업의 전체 자금흐름에 대한 공헌은 그리 크지 않다"]]},{"t":"table","title":"전략과 기업결합","head":["개념","내용"],"rows":[["차별화 대응","기업의 기존 활동에 단지 새로운 특성, 서비스, 기술 등을 더하여 경쟁자와 대응하는 것이다"],["컨글로머레이트(conglomerate)","다른 업종이나 기업 간 주식 매입을 통해 결합한 대기업 형태이다"]]}]};
